const cfg = $('Workflow Config').first().json;
const rows = $input.all().map(r => r.json || {});

const norm = k => String(k).toLowerCase().replace(/[^a-z0-9]/g, '');

const isTicked = v => {
  if (typeof v === 'boolean') return v === true;
  if (typeof v === 'number') return v === 1;
  const s = String(v ?? '').trim().toLowerCase();
  return ['true', 'yes', 'y', '1', 'x', 'on', 'checked', '✓', '✔', '☑'].includes(s);
};

let sw = '';
for (const j of rows) {
  const keys = Object.keys(j).filter(k => k !== 'row_number' && k !== 'error');
  if (!keys.length) continue;
  const preferred = keys.find(k => /master|switch|on.?off/i.test(k));
  const v = String(j[preferred || keys[0]] ?? '').trim().toUpperCase();
  if (v) { sw = v; break; }
}

const selected = [];
const allCities = [];
const trace = [];
let includeUnknown = false;

for (const j of rows) {
  const keys = Object.keys(j).filter(k => k !== 'row_number' && k !== 'error');
  if (!keys.length) continue;

  let city = '';
  let enabled = null;
  let enabledKeyUsed = null;

  for (const k of keys) {
    const nk = norm(k);
    const val = j[k];

    if (!city && (nk.includes('city') || nk.includes('location'))) {
      city = String(val ?? '').trim();
    }

    if (
      enabled === null &&
      (nk.includes('enabled') || nk.includes('enable') || nk.includes('selected') ||
       nk.includes('active') || nk.includes('apply') || nk.includes('tick') || nk.includes('include'))
    ) {
      enabled = isTicked(val);
      enabledKeyUsed = k;
    }
  }

  if (!city) continue;

  if (norm(city) === 'includeunknowncity') {
    includeUnknown = enabled === null ? false : enabled;
    continue;
  }

  allCities.push(city);
  trace.push({ city, enabledKeyUsed, enabled, rawValue: j[enabledKeyUsed], rawType: typeof j[enabledKeyUsed] });

  if (enabled === true || enabled === null) {
    selected.push(city);
  }
}

const parts = new Intl.DateTimeFormat('en-GB', {
  timeZone: cfg.timezone, hour: '2-digit', minute: '2-digit', hour12: false,
}).formatToParts(new Date());
const hour = parseInt(parts.find(p => p.type === 'hour').value, 10);
const minute = parseInt(parts.find(p => p.type === 'minute').value, 10);
const minutesNow = hour * 60 + minute;
const withinWindow = minutesNow >= Number(cfg.window_start_hour) * 60 && minutesNow < Number(cfg.window_end_hour) * 60;
const proceed = sw === 'ON' && withinWindow;
const reason = sw !== 'ON'
  ? `Master switch is ${sw || 'MISSING'} (Settings!A2 must be ON)`
  : (withinWindow ? 'OK' : `Outside send window (${cfg.window_start_hour}:00-${cfg.window_end_hour}:00 ${cfg.timezone})`);

return [{
  json: {
    trace,
    proceed,
    master_switch: sw || '(not found)',
    ist_time: `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`,
    within_window: withinWindow,
    reason,
    selected_cities: selected,
    known_cities: allCities,
    include_unknown_city: includeUnknown,
    city_filter_active: selected.length > 0,
  }
}];

/*
 * Turns the Sheets API metadata into one item per raw data tab.
 * Tabs listed in Workflow Config > excluded_tabs (Settings/Tracker/Log) are skipped.
 * If you later merge everything into a single sheet, this keeps working:
 * just leave one data tab in the spreadsheet.
 */
const cfg = $('Workflow Config').first().json;
const excluded = String(cfg.excluded_tabs || '')
  .split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const titles = ($input.first().json.sheets || [])
  .filter(s => !(s.properties || {}).hidden)
  .map(s => (s.properties || {}).title)
  .filter(Boolean);
const selected = titles.filter(t => !excluded.includes(t.toLowerCase()));
return selected.map(t => ({ json: { sheetTitle: t } }));

/*
 * Normalizes messy rows from every raw tab into one consistent structure,
 * then overlays saved outreach state from the Tracker tab (matched by email).
 *  - Headers are matched case/space/underscore-insensitively against synonyms
 *  - Empty rows are dropped
 *  - Rows without a valid email address are dropped (per spec)
 *  - Missing optional fields are preserved and flagged in `data_flags`
 *  - Duplicate emails across tabs: first occurrence wins
 */
const FIELD_SYNONYMS = {
  company: ['company', 'companyname', 'org', 'organisation', 'organization', 'employer', 'firm', 'startup'],
  recruiter_name: ['recruitername', 'recruiter', 'name', 'contactname', 'contact', 'hrname', 'hr', 'person', 'pocname', 'poc', 'fullname', 'contactperson', 'hiringmanager'],
  email: ['email', 'emailid', 'emailaddress', 'mail', 'mailid', 'contactemail', 'recruiteremail', 'workemail', 'hremail'],
  job_role: ['jobrole', 'role', 'position', 'jobtitle', 'title', 'designation', 'profile', 'opening', 'vacancy', 'jobposition'],
  linkedin: ['linkedin', 'linkedinurl', 'linkedinprofile', 'linkedinlink', 'li', 'profileurl'],
  source: ['source', 'foundvia', 'platform', 'portal', 'via', 'jobboard', 'referral', 'sourcedfrom'],
  status: ['status', 'outreachstatus', 'mailstatus', 'stage'],
  mail_count: ['mailcount', 'mailssent', 'emailssent', 'mailno', 'followupcount', 'emailcount', 'count'],
  last_mail_date: ['lastmaildate', 'lastmail', 'lastsent', 'lastemaildate', 'lastcontacted', 'lastsentdate'],
  next_mail_date: ['nextmaildate', 'nextmail', 'nextfollowup', 'nextsend', 'followupdate', 'nextsenddate'],
  reply_status: ['replystatus', 'reply', 'replied', 'response', 'responsestatus'],
  gmail_thread_id: ['gmailthreadid', 'threadid', 'thread', 'gmailthread'],
  notes: ['notes', 'note', 'remarks', 'comments', 'comment', 'extra'],
  city: ['city', 'location', 'joblocation', 'worklocation', 'baselocation', 'place', 'region',
         'office', 'officelocation', 'hq', 'headquarters', 'basedin', 'area', 'geo', 'citytown'],
};
const TRACKING_FIELDS = ['status', 'mail_count', 'last_mail_date', 'next_mail_date', 'reply_status', 'gmail_thread_id', 'notes'];
const OPTIONAL_INFO_FIELDS = ['company', 'recruiter_name', 'job_role', 'linkedin', 'source', 'city'];
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const norm = k => String(k).toLowerCase().replace(/[^a-z0-9]/g, '');

// --- Tracker rows (canonical outreach state), keyed by email ---
const tracker = {};
for (const t of $('Read Tracker State').all()) {
  const j = t.json || {};
  const em = String(j.email || '').trim().toLowerCase();
  if (EMAIL_RE.test(em)) tracker[em] = j;
}

// --- Raw rows from all tabs ---
const tabItems = $('Select Raw Data Tabs').all();
const rawItems = $('Read Rows From All Tabs').all();
const out = [];
const seen = new Set();

for (const it of rawItems) {
  const raw = it.json || {};
  if (raw.error) continue; // a tab failed to read; its error item is skipped, run continues

  // Resolve which tab this row came from (paired item -> tab list)
  let idx = 0;
  const p = it.pairedItem;
  if (typeof p === 'number') idx = p;
  else if (p && typeof p.item === 'number') idx = p.item;
  const sourceTab = (tabItems[idx] && tabItems[idx].json.sheetTitle) || 'unknown';

  const rawKeys = Object.keys(raw).filter(k => k !== 'row_number');

  // Drop fully empty rows
  const hasAnyValue = rawKeys.some(k => raw[k] !== null && raw[k] !== undefined && String(raw[k]).trim() !== '');
  if (!hasAnyValue) continue;

  // Map raw headers -> canonical fields
  const byNorm = {};
  for (const k of rawKeys) { const nk = norm(k); if (!(nk in byNorm)) byNorm[nk] = k; }
  const used = new Set();
  const row = {};
  for (const [field, synonyms] of Object.entries(FIELD_SYNONYMS)) {
    let val = '';
    for (const syn of synonyms) {
      const rk = byNorm[syn];
      if (rk !== undefined && !used.has(rk)) {
        const v = raw[rk];
        if (v !== null && v !== undefined && String(v).trim() !== '') {
          val = String(v).trim();
          used.add(rk);
          break;
        }
      }
    }
    row[field] = val;
  }

  // Drop rows with missing/invalid email addresses (per spec)
  row.email = row.email.toLowerCase();
  if (!EMAIL_RE.test(row.email)) continue;

  // Dedupe across tabs
  if (seen.has(row.email)) continue;
  seen.add(row.email);

  // Overlay Tracker state - Tracker is the source of truth for outreach state
  const saved = tracker[row.email];
  if (saved) {
    for (const f of TRACKING_FIELDS) {
      const v = saved[f];
      if (v !== null && v !== undefined && String(v).trim() !== '') row[f] = String(v).trim();
    }
  }

  // Defaults + flags: missing fields never break the row, they are just marked
  const flags = [];
  for (const f of OPTIONAL_INFO_FIELDS) if (!row[f]) flags.push('missing:' + f);
  if (!row.status) row.status = 'Pending';
  if (!row.reply_status) row.reply_status = 'No Reply';
  const mc = parseInt(row.mail_count, 10);
  row.mail_count = Number.isFinite(mc) && mc >= 0 ? mc : 0;
  row.source_tab = sourceTab;
  row.source_row = (raw.row_number !== undefined && raw.row_number !== null) ? raw.row_number : '';
  row.data_flags = flags.join(', ');

  out.push({ json: row });
}

return out;

/*
 * Decides what to do with each contact this run:
 *   send  - mail 1 immediately, or a due follow-up
 *   close - already received max mails -> mark Closed
 *   wait  - follow-up exists but is not due yet
 *   skip  - terminal status, never mail again
 *
 * Follow-up cadence (days after previous mail):
 *   Mail 1 -> +2 days
 *   Mail 2 -> +5 days
 *   Mail 3 -> +9 days
 *   Mail 4 -> +14 days
 *
 * After Mail 5 the row is Closed.
 */

const cfg = $('Workflow Config').first().json;

// Default follow-up gaps (days)
let gaps = {
  '1': 2,
  '2': 5,
  '3': 9,
  '4': 14,
};

try {
  gaps = JSON.parse(cfg.followup_gap_days);
} catch (e) {
  // keep defaults
}

const MAX_MAILS = Number(cfg.max_mails) || 5;

const TERMINAL = [
  'Closed',
  'Replied',
  'Got Reply',
  'Rejected',
  'Mail Not Found',
  'Skipped',
  'Error'
];

const now = Date.now();

return $input.all().map(item => {

  const c = { ...item.json };

  const status = String(c.status || 'Pending').trim();
  const mailCount = Number(c.mail_count) || 0;

  if (TERMINAL.includes(status)) {

    c.action = 'skip';
    c.action_reason = `Status "${status}" is terminal`;

  }

  else if (mailCount >= MAX_MAILS) {

    c.action = 'close';
    c.action_reason = `Reached maximum of ${MAX_MAILS} mails`;

  }

  else if (mailCount === 0) {

    c.action = 'send';
    c.action_reason = 'First outreach mail';

  }

  else {

    let due = Date.parse(c.next_mail_date || '');

    if (!Number.isFinite(due)) {

      const last = Date.parse(c.last_mail_date || '');

      const gapDays = Number(gaps[String(mailCount)]) || 2;

      due = Number.isFinite(last)
        ? last + gapDays * 24 * 60 * 60 * 1000
        : now;

    }

    if (now >= due) {

      c.action = 'send';
      c.action_reason = `Follow-up mail ${mailCount + 1} is due`;

    } else {

      c.action = 'wait';
      c.action_reason = `Next mail due at ${new Date(due).toISOString()}`;

    }

  }

  return {
    json: c
  };

});

/*
 * End-of-run summary. Per-row outcomes are appended to the Log tab.
 */
const gates = $('Check Gates: Switch + Time Window').first().json;
const normalized = $('Normalize & Merge Dataset').all().length;
const decided = $('Decide Next Action').all().map(i => i.json);
const counts = {};
for (const d of decided) counts[d.action] = (counts[d.action] || 0) + 1;

return [{ json: {
  finished_at: new Date().toISOString(),
  city_filter_active: gates.city_filter_active === true,
  selected_cities: gates.selected_cities || [],
  contacts_after_city_filter: decided.length,
  contacts_excluded_by_city: normalized - decided.length,
  contacts_processed: decided.length,
  planned_actions: counts,
  note: 'Per-row outcomes are in the Log tab of the spreadsheet.',
} }];

/*
 * Interprets the Gmail search result.
 * The search looked for any message FROM the contact received after our last mail
 * (covers replies inside the thread and fresh emails from them).
 * If the check itself errored, we do NOT send this run (never risk mailing someone
 * who already replied) - the row is retried on the next run.
 */
const contact = $('Loop Over Contacts').first().json;
const items = $input.all();
const found = items.filter(i => i.json && !i.json.error && (i.json.id || i.json.threadId));
const checkFailed = items.some(i => i.json && i.json.error);
const replied = found.length > 0;
let threadId = contact.gmail_thread_id || '';
if (replied && found[0].json.threadId) threadId = found[0].json.threadId;

return [{ json: {
  ...contact,
  replied,
  check_failed: !replied && checkFailed,
  gmail_thread_id: threadId,
  // used by the interview-scheduling branch to pull the full reply text
  reply_message_id: replied ? (found[0].json.id || '') : '',
  reply_snippet: replied ? String(found[0].json.snippet || '') : '',
} }];

/*
 * Builds the Tracker/Log payload when a reply was detected
 * (or when the reply check failed and sending was skipped as a precaution).
 * Also folds in the outcome of the interview-scheduling branch.
 */
const cfg = $('Workflow Config').first().json;
const c = $('Detect Interview Intent').first().json;
const failed = c.check_failed === true;

// The calendar node only runs on the confident branch - guard the reference.
let eventId = '';
let eventLink = '';
try {
  const ev = $('Create Interview Calendar Event').first().json;
  eventId = ev.id || '';
  eventLink = ev.htmlLink || '';
} catch (e) { /* no event was created this run */ }

const calendarNote = eventId
  ? `Interview event created (${c.event_start})`
  : (c.interview_intent ? c.interview_parse_result : '');

return [{ json: {
  ...c,
  status: failed ? c.status : 'Replied',
  reply_status: failed ? c.reply_status : 'Got Reply',
  next_mail_date: failed ? (c.next_mail_date || '') : '',
  calendar_event_id: eventId,
  calendar_event_link: eventLink,
  notes: [c.notes, calendarNote, c.interview_notes ? 'Reply: ' + c.interview_notes.slice(0, 400) : '']
    .filter(Boolean).join(' | ').slice(0, 1000),
  log_timestamp: new Date().toLocaleString('en-IN', { timeZone: cfg.timezone }),
  log_mail_number: Number(c.mail_count) || 0,
  log_result: failed
    ? 'Reply check failed - send skipped this run (will retry)'
    : 'Reply detected - follow-ups stopped' + (calendarNote ? ' | ' + calendarNote : ''),
  log_thread_id: c.gmail_thread_id || '',
  log_duration_ms: Date.now() - Date.parse(cfg.run_started_at),
} }];

/*
 * The contact already received all 5 mails -> mark the row Closed.
 */
const cfg = $('Workflow Config').first().json;
const c = $input.first().json;

return [{ json: {
  ...c,
  status: 'Closed',
  next_mail_date: '',
  log_timestamp: new Date().toLocaleString('en-IN', { timeZone: cfg.timezone }),
  log_mail_number: Number(c.mail_count) || 0,
  log_result: 'Sequence complete (5 mails) - marked Closed',
  log_thread_id: c.gmail_thread_id || '',
  log_duration_ms: Date.now() - Date.parse(cfg.run_started_at),
} }];

/*
 * Generate Personalized Email (v3)
 * Updated for backend / full-stack / AI-native software roles.
 */

const cfg = $('Workflow Config').first().json;
const c = $input.first().json;

const clean = v => String(v || '').trim();

const company = clean(c.company);
const role = clean(c.job_role);
const source = clean(c.source);

const previousMails = Number(c.mail_count) || 0;
const mailNumber = previousMails + 1;

const me = clean(cfg.sender_name);
const phone = clean(cfg.sender_phone);
const linkedin = clean(cfg.sender_portfolio);
const headline = clean(cfg.sender_headline);

let recruiter = clean(c.recruiter_name)
  .replace(/^(mr|mrs|ms|dr)\.?\s+/i, '')
  .replace(/\s*\((.*?)\)\s*/g, ' ')
  .trim();

const validName =
  recruiter &&
  /^[A-Za-z][A-Za-z.'\- ]+$/.test(recruiter) &&
  !/^(hr|team|recruiter|talent|careers|admin|info|hiring)$/i.test(recruiter);

const greeting = validName
  ? `Hi ${recruiter.split(" ")[0]},`
  : company
      ? `Dear ${company} Hiring Team,`
      : `Dear Hiring Team,`;

const roleText = role || "Software Development / AI Internship";

const subjectMap = {
  1: company
      ? `Application for ${roleText} at ${company}`
      : `Application for ${roleText}`,
  2: company
      ? `Following up on my application at ${company}`
      : `Following up on my application`,
  3: company
      ? `Checking in regarding my application at ${company}`
      : `Checking in regarding my application`,
  4: company
      ? `Final follow-up regarding my application at ${company}`
      : `Final follow-up regarding my application`,
  5: company
      ? `Last follow-up regarding my application at ${company}`
      : `Last follow-up regarding my application`
};

const subject = subjectMap[mailNumber];

let body = "";

if (mailNumber === 1) {

body = `${greeting}

I'm Shashwat Verma, a final-year B.Tech student specializing in Artificial Intelligence & Data Science with hands-on experience building production-grade backend systems, AI-powered applications, and full-stack products.

I'm reaching out regarding the ${roleText}${company ? ` opportunity at ${company}` : ""}${source ? ` that I found via ${source}` : ""}.

Through my internships, I've gained hands-on experience with:

• Backend Engineering (FastAPI, PostgreSQL, Redis, REST APIs)
• Full-Stack Development (React, Next.js, TypeScript)
• Clean Architecture, Domain-Driven Design (DDD), and Hexagonal Architecture
• AI Agents, RAG Pipelines, and Workflow Automation
• Docker, Git, and Production Software Development

I'm currently working as a Backend / AI Engineer Intern, where I lead the backend architecture of an AI-native multi-tenant CRM platform.

My recent responsibilities include:

• Architecting scalable systems using Clean Architecture, DDD, and Hexagonal Architecture
• Building 20+ FastAPI REST APIs with PostgreSQL and Docker
• Designing plug-and-play connector modules and AI-powered CRM automation
• Mentoring teammates while driving backend architectural decisions focused on scalability and maintainability

I'm currently looking for opportunities in Backend Engineering, Full-Stack Development, or AI-native software systems where I can contribute while continuing to learn from experienced engineers.

My resume is attached for your review.

I would greatly appreciate the opportunity to discuss how I could contribute to your team.

Thank you for your time and consideration.

Best regards,

${me}
${headline}
${phone}
${linkedin}`;

} else if (mailNumber === 2) {
  body = `${greeting}

I hope you're doing well.

I wanted to follow up on my application${company ? ` at ${company}` : ""}.

I understand hiring teams are often busy, so I just wanted to check whether my profile has had a chance to be reviewed.

If helpful, I can share more details about my backend, full-stack, or AI-related project work.

Thank you for your time.

Best regards,

${me}
${phone}`;
} else if (mailNumber === 3) {
  body = `${greeting}

Just checking in once again regarding my application.

I'm still very interested in the opportunity and would appreciate any update whenever convenient.

Thank you.

Best regards,

${me}
${phone}`;
} else if (mailNumber === 4) {
  body = `${greeting}

I know inboxes get busy, so I wanted to send one final reminder regarding my application.

If there isn't a suitable opening currently, I'd still appreciate being considered for future opportunities that match my profile.

Thank you for your time.

Best regards,

${me}
${phone}`;
} else {
  body = `${greeting}

This will be my final follow-up regarding my application.

Thank you for considering my profile.

If an opportunity becomes available in the future, I'd be glad to reconnect.

Wishing you and your team continued success.

Best regards,

${me}
${phone}`;
}

return [{
  json: {
    ...c,
    mail_number: mailNumber,
    subject,
    body
  }
}];

/*
 * A mail was sent successfully: bump the counters, capture the Gmail thread id
 * (so every follow-up stays in the same conversation) and schedule the next mail.
 */
const cfg = $('Workflow Config').first().json;
const c = $('Generate Personalized Email').first().json;
const sent = $input.first().json || {};
let gaps = { '1': 2, '2': 1, '3': 1.5, '4': 3 };
try { gaps = JSON.parse(cfg.followup_gap_hours); } catch (e) { /* keep defaults */ }

const newCount = (Number(c.mail_count) || 0) + 1;
const maxMails = Number(cfg.max_mails) || 5;
const gapH = Number(gaps[String(newCount)]) || 0;
const threadId = sent.threadId || c.gmail_thread_id || '';

return [{ json: {
  ...c,
  mail_count: newCount,
  status: `Mail ${newCount} Sent`,
  last_mail_date: new Date().toISOString(),
  next_mail_date: newCount < maxMails && gapH > 0
    ? new Date(Date.now() + gapH * 3600 * 1000).toISOString()
    : '',
  gmail_thread_id: threadId,
  log_timestamp: new Date().toLocaleString('en-IN', { timeZone: cfg.timezone }),
  log_mail_number: newCount,
  log_result: `Mail ${newCount} sent successfully`,
  log_thread_id: threadId,
  log_duration_ms: Date.now() - Date.parse(cfg.run_started_at),
} }];

/*
 * A send failed. Classify the error:
 *  - invalid / unknown / unavailable recipient -> status "Mail Not Found" (never retried)
 *  - anything else                             -> status "Error" (never retried automatically;
 *    clear the status cell in the Tracker tab to re-enable the row)
 */
const cfg = $('Workflow Config').first().json;
const c = $('Generate Personalized Email').first().json;
const errJson = $input.first().json || {};
const msg = String(
  (errJson.error && errJson.error.message) || errJson.error || errJson.message || 'Unknown send error'
);
const NOT_FOUND_RE = /invalid (to|recipient|address)|address (not found|could ?n.t be found)|recipient address|mailbox (unavailable|not found|does not exist|full)|user unknown|no ?such ?user|domain not found|550|553|invalid to header/i;
const permanent = NOT_FOUND_RE.test(msg);

return [{ json: {
  ...c,
  status: permanent ? 'Mail Not Found' : 'Error',
  next_mail_date: '',
  notes: [c.notes, `[${new Date().toISOString()}] send failed: ${msg}`.slice(0, 300)]
    .filter(Boolean).join(' | '),
  log_timestamp: new Date().toLocaleString('en-IN', { timeZone: cfg.timezone }),
  log_mail_number: (Number(c.mail_count) || 0) + 1,
  log_result: (permanent ? 'Mail Not Found: ' : 'Error: ') + msg.slice(0, 200),
  log_thread_id: c.gmail_thread_id || '',
  log_duration_ms: Date.now() - Date.parse(cfg.run_started_at),
} }];

/*
 * Re-attaches the email JSON (from Generate Personalized Email) to the resume binary
 * loaded by "Load Resume File", so the Gmail nodes receive both in one item.
 * Binary property name is `resume` - referenced by both Gmail send nodes.
 */
const email = $('Generate Personalized Email').first().json;
const item = $input.first();
const binary = item.binary || {};
const hasResume = !!binary.resume;

return [{
  json: { ...email, resume_attached: hasResume },
  binary,
}];

/*
 * Decides whether a reply is a genuine interview-scheduling message and, if so,
 * extracts a concrete date + time (Asia/Kolkata).
 *
 * An event is created ONLY when ALL of these hold:
 *   - an interview/scheduling keyword is present
 *   - an unambiguous date was parsed
 *   - an unambiguous time was parsed
 * Anything vaguer is left alone: the reply text is preserved on the row
 * (interview_notes) and no calendar event is created.
 */
const cfg = $('Workflow Config').first().json;
const base = $('Evaluate Reply Result').first().json;
const msg = $input.first().json || {};

const text = String(
  msg.text || msg.textPlain || msg.snippet || base.reply_snippet || ''
).replace(/\s+/g, ' ').trim();
const subject = String(msg.subject || '');
const haystack = (subject + ' ' + text).toLowerCase();

const INTERVIEW_RE = /\b(interview|schedule[d]?|scheduling|availability|available|slot|call\b|meeting|meet\b|discussion round|technical round|hr round|calendar invite|google meet|zoom|teams call)\b/;
const NEGATIVE_RE = /\b(unfortunately|not (moving|proceeding)|regret|rejected|no longer|position (is )?(closed|filled)|out of office|auto[- ]?reply)\b/;
const hasIntent = INTERVIEW_RE.test(haystack) && !NEGATIVE_RE.test(haystack);

const MONTHS = { jan:1, feb:2, mar:3, apr:4, may:5, jun:6, jul:7, aug:8, sep:9, sept:9, oct:10, nov:11, dec:12 };
const now = new Date();
let year = null, month = null, day = null;

// ISO: 2026-08-12
let m = text.match(/\b(20\d{2})-(\d{1,2})-(\d{1,2})\b/);
if (m) { year = +m[1]; month = +m[2]; day = +m[3]; }
// 12 Aug [2026] / 12th August
if (month === null) {
  m = text.match(/\b(\d{1,2})(?:st|nd|rd|th)?\s+(jan|feb|mar|apr|may|jun|jul|aug|sept|sep|oct|nov|dec)[a-z]*\.?\,?\s*(20\d{2})?/i);
  if (m) { day = +m[1]; month = MONTHS[m[2].toLowerCase()]; year = m[3] ? +m[3] : null; }
}
// Aug 12[, 2026]
if (month === null) {
  m = text.match(/\b(jan|feb|mar|apr|may|jun|jul|aug|sept|sep|oct|nov|dec)[a-z]*\.?\s+(\d{1,2})(?:st|nd|rd|th)?\,?\s*(20\d{2})?/i);
  if (m) { month = MONTHS[m[1].toLowerCase()]; day = +m[2]; year = m[3] ? +m[3] : null; }
}
// 12/08/2026 or 12-08-2026 (day-first, Indian convention)
if (month === null) {
  m = text.match(/\b(\d{1,2})[\/\-](\d{1,2})[\/\-](20\d{2})\b/);
  if (m) { day = +m[1]; month = +m[2]; year = +m[3]; }
}

// Time: 3pm / 3:30 PM / 15:00 hrs
let hour = null, minute = 0;
m = text.match(/\b(\d{1,2})(?::(\d{2}))?\s*(a\.?m\.?|p\.?m\.?)\b/i);
if (m) {
  hour = +m[1] % 12;
  minute = m[2] ? +m[2] : 0;
  if (/^p/i.test(m[3])) hour += 12;
} else {
  m = text.match(/\b([01]?\d|2[0-3]):([0-5]\d)\s*(?:hrs?|hours)?\b/);
  if (m) { hour = +m[1]; minute = +m[2]; }
}

// Fill in a missing year: assume the next occurrence, never the past
if (month !== null && day !== null && year === null) {
  year = now.getUTCFullYear();
  const probe = Date.UTC(year, month - 1, day) - 5.5 * 3600 * 1000;
  if (probe < now.getTime() - 3 * 24 * 3600 * 1000) year += 1;
}

const dateOk = year !== null && month >= 1 && month <= 12 && day >= 1 && day <= 31;
const timeOk = hour !== null && hour >= 0 && hour <= 23;

let startIso = '', endIso = '';
if (dateOk && timeOk) {
  // Asia/Kolkata is a fixed UTC+05:30 offset - no DST to handle
  const startMs = Date.UTC(year, month - 1, day, hour, minute) - 5.5 * 3600 * 1000;
  const durMin = Number(cfg.interview_event_duration_min) || 45;
  startIso = new Date(startMs).toISOString();
  endIso = new Date(startMs + durMin * 60 * 1000).toISOString();
}

const createEvent = hasIntent && dateOk && timeOk;

return [{ json: {
  ...base,
  interview_intent: hasIntent,
  create_event: createEvent,
  event_start: startIso,
  event_end: endIso,
  event_title: `Interview - ${base.company || base.email}${base.job_role ? ' (' + base.job_role + ')' : ''}`,
  interview_notes: text.slice(0, 900),
  interview_parse_result: createEvent
    ? `Parsed ${startIso}`
    : (hasIntent ? 'Interview intent detected but date/time ambiguous - no event created' : 'No interview intent'),
} }];

/*
 * Apply City Filter
 * Keeps only contacts based in the cities you ticked in the Settings tab.
 *
 *  - Multi-select: tick Bangalore + Delhi and both are processed.
 *  - Nothing is ever deleted. Rows for unticked cities are simply not crawled
 *    or mailed this run; their sheet rows and tracker state are left untouched,
 *    so ticking that city later resumes them exactly where they left off.
 *  - No city ticked at all  -> filter is OFF, every contact passes (safe default).
 *  - Rows whose city is blank/unrecognized are excluded unless you tick the
 *    `include_unknown_city` control row in Settings.
 *
 * Matching is forgiving: case-insensitive, punctuation-insensitive, substring-aware
 * ("Bengaluru, KA (Hybrid)" matches Bangalore), and alias-aware via the
 * `city_aliases` map in Workflow Config.
 */
const cfg = $('Workflow Config').first().json;
const gates = $('Check Gates: Switch + Time Window').first().json;

const selected = Array.isArray(gates.selected_cities) ? gates.selected_cities : [];
const includeUnknown = gates.include_unknown_city === true;
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

let aliases = {};
try { aliases = JSON.parse(cfg.city_aliases || '{}'); } catch (e) { /* fall back to exact matching */ }

// Build the set of accepted spellings for each ticked city
const accepted = [];
for (const city of selected) {
  const canonical = norm(city);
  const variants = new Set([canonical]);
  for (const [key, list] of Object.entries(aliases)) {
    const keyN = norm(key);
    const listN = (list || []).map(norm);
    if (keyN === canonical || listN.includes(canonical)) {
      variants.add(keyN);
      listN.forEach(v => variants.add(v));
    }
  }
  accepted.push({ label: city, variants: [...variants].filter(Boolean) });
}

const kept = [];
let excludedCity = 0, excludedUnknown = 0;

for (const it of $input.all()) {
  const c = { ...it.json };

  // Filter disabled -> everything passes through untouched
  if (accepted.length === 0) {
    c.city_match = 'filter-off';
    kept.push({ json: c });
    continue;
  }

  const rowCity = norm(c.city);
  if (!rowCity) {
    // No city column on this sheet, or cell left blank -> can't filter, so pass it through.
    c.city_match = 'no-city-column';
    kept.push({ json: c });
    continue;
  }

  // A row matches if any accepted spelling appears in its city text (or vice versa)
  const hit = accepted.find(a => a.variants.some(v =>
    rowCity === v || rowCity.includes(v) || v.includes(rowCity)
  ));

  if (hit) {
    c.city_match = hit.label;
    kept.push({ json: c });
  } else if (includeUnknown && !accepted.some(a => a.variants.some(v => rowCity.includes(v)))) {
    excludedCity++;   // recognized city, just not ticked -> still excluded
  } else {
    excludedCity++;
  }
}

// Surfaced in the execution log so a silent zero-send run is easy to diagnose
console.log(JSON.stringify({
  city_filter_active: accepted.length > 0,
  selected_cities: selected,
  contacts_in: $input.all().length,
  contacts_kept: kept.length,
  excluded_wrong_city: excludedCity,
  excluded_missing_city: excludedUnknown,
  include_unknown_city: includeUnknown,
}));

return kept;
